<script>
import { blogPosts } from "@/constants/blogPosts";
import { formatDotDate } from "@/utils/date";
import { vReveal, observeOnce } from "@/composables/useScrollReveal";

// "20+" → { target: 20, suffix: "+" }。数値で始まらないものは null
function parseStatNumber(number) {
  const m = /^(\d+)(.*)$/.exec(number);
  return m ? { target: Number(m[1]), suffix: m[2] } : null;
}

const BADGE_TEXT = "遊び心も、積み荷のうち";

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export default {
  directives: { reveal: vReveal },
  data: () => ({
    stats: [
      { number: "5+", label: "Years Experience" },
      { number: "20+", label: "Projects Delivered" },
      { number: "3", label: "Core Services" },
      { number: "100%", label: "Client Focused" },
    ],
    // カウントアップ中の表示値（初期値は0。可視化前はヒーロー下で見えない）
    displayStats: [],
    // ターミナルの表示済み行数（プロンプト+出力4行+末尾プロンプト）
    termLines: 0,
    // お知らせ: 執筆日（front-matterのdate）の新しい順に5件
    newsPosts: [...blogPosts]
      .sort((a, b) => (b.date || "").localeCompare(a.date || ""))
      .slice(0, 5),
    stopStatsObserver: null,
    // イースターエッグ（船の出航）の状態
    badgeText: BADGE_TEXT,
    badgeFading: false,
    sailing: false, // 多重発火防止ロック
    voyaging: false, // バッジ内の船を隠す（reduced-motion時は隠さない）
    voyage: null, // { phase: "depart"|"return", style: {...} }
    docked: false, // 帰港後、バッジの揺れをニュートラル位相から再開させる
    features: [
      {
        icon: "mdi-cellphone-link",
        title: "クロスプラットフォーム開発",
        en: "Cross-Platform Development",
        description:
          "iOS / Android / Web を横断し、企画から運用まで一気通貫で支援。少人数チームでも高品質かつスピーディーなリリースを実現します。",
        points: [
          "ネイティブ品質にこだわったUI/UX",
          "Kotlin MultiplatformによるiOS / Android同時開発",
          "リリース後の運用・グロースまで伴走",
        ],
        tags: ["Swift", "Kotlin", "Flutter", "Vue"],
        theme: "feat-navy",
      },
      {
        icon: "mdi-brain",
        title: "AI・機械学習",
        en: "AI & Machine Learning",
        description:
          "LLMを活用したAIエージェント開発から、AI駆動開発による生産性向上まで。現場で本当に使えるAI活用をご提案します。",
        points: [
          "LLM / RAGを用いたシステム構築",
          "業務を自動化するAIエージェント開発",
          "AI駆動開発の導入・定着支援",
        ],
        tags: ["LLM", "RAG", "Python", "Codex", "Claude Code"],
        theme: "feat-terra",
      },
      {
        icon: "mdi-chart-bubble",
        title: "チーム開発支援",
        en: "Team Development",
        description:
          "アジャイル・スクラムの導入から、CI/CDによる開発基盤づくりまで。チームが自走できる仕組みを構築します。",
        points: [
          "スクラム導入・改善の伴走支援",
          "CI/CDパイプラインの構築・整備",
          "ふりかえり文化の定着サポート",
        ],
        tags: ["Agile", "Scrum", "CI/CD"],
        theme: "feat-olive",
      },
    ],
  }),
  created() {
    this.displayStats = this.stats.map((s) =>
      parseStatNumber(s.number) ? `0${parseStatNumber(s.number).suffix}` : s.number
    );
  },
  mounted() {
    // ターミナルが見えたら行を順次表示（reduced-motion 時は即全表示・即最終値）
    this.stopStatsObserver = observeOnce(this.$refs.statsRef, this.runTerminal);
  },
  beforeUnmount() {
    this.stopStatsObserver?.();
  },
  methods: {
    formatDotDate,
    // ターミナルの行を1行ずつ表示する。reduced-motion 時は即全表示
    runTerminal() {
      const total = this.stats.length + 2; // プロンプト + 出力4行 + 末尾プロンプト
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        this.termLines = total;
        this.displayStats = this.stats.map((s) => s.number);
        return;
      }
      const tick = () => {
        this.termLines += 1;
        if (this.termLines === 2) this.animateStats(); // 最初の出力行と同時にカウント開始
        if (this.termLines < total) setTimeout(tick, 220);
      };
      tick();
    },
    // バッジ文言をフェードで差し替える
    async swapBadgeText(text) {
      this.badgeFading = true;
      await wait(250);
      this.badgeText = text;
      this.badgeFading = false;
      await wait(250);
    },
    // 航海(voyage-x)のアニメ完了を待つ。固定タイマーだとCSSアニメと数フレーム
    // ずれて最終位置へスナップして見えるため、animationendに同期する
    waitVoyageEnd(timeoutMs) {
      const el = this.$refs.voyageRef;
      if (!el) return wait(timeoutMs);
      return new Promise((resolve) => {
        const finish = () => {
          el.removeEventListener("animationend", onEnd);
          clearTimeout(timer);
          resolve();
        };
        const onEnd = (e) => {
          // 子アイコンの voyage-bob の完了は無視（scoped名はハッシュ付きなので前方一致）
          if (!e.animationName.startsWith("voyage-x")) return;
          finish();
        };
        el.addEventListener("animationend", onEnd);
        const timer = setTimeout(finish, timeoutMs); // アニメが動かない環境の保険
      });
    },
    // イースターエッグ: 船がバッジから出航し、ひと回りして帰港する
    async setSail() {
      if (this.sailing) return;
      this.sailing = true;

      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        // 動きは出さず、文言だけ挨拶して戻す
        await this.swapBadgeText("いってらっしゃい");
        await wait(2000);
        await this.swapBadgeText(BADGE_TEXT);
        this.sailing = false;
        return;
      }

      const hero = this.$refs.heroRef;
      // 座標基準はアイコンではなくボタン。アイコンは入港/揺れアニメのtransformで
      // 動くため、クリック時点の位相によって測定がぶれて着岸位置がずれる
      const shipBtn = this.$refs.shipBtnRef;
      const badge = this.$refs.badgeRef;
      if (!hero || !shipBtn || !badge) {
        this.sailing = false;
        return;
      }
      const heroRect = hero.getBoundingClientRect();
      const shipRect = shipBtn.getBoundingClientRect();
      const startLeft = shipRect.left - heroRect.left;
      const startTop = shipRect.top - heroRect.top;

      // 文言切替でバッジ幅が変わらないよう現在幅で固定
      // （offsetWidthは整数に切り捨てられ実幅より狭くなり折り返しの原因になるため、切り上げる）
      badge.style.width = `${Math.ceil(badge.getBoundingClientRect().width)}px`;

      // 出航: バッジ位置 → ヒーロー左端の外へ
      this.voyaging = true;
      this.docked = false;
      this.voyage = {
        phase: "depart",
        style: {
          left: `${startLeft}px`,
          top: `${startTop}px`,
          "--dist": `${-(startLeft + 40)}px`,
        },
      };
      this.swapBadgeText("ただいま出航中…");
      await this.$nextTick();
      await this.waitVoyageEnd(2600);
      this.voyage = null;

      // 沖合を航海中
      await wait(1200);

      // 帰港: ヒーロー左端の外 → バッジ定位置
      this.voyage = {
        phase: "return",
        style: {
          left: "-40px",
          top: `${startTop}px`,
          "--dist": `${startLeft + 40}px`,
        },
      };
      await this.$nextTick();
      await this.waitVoyageEnd(2600);

      // 船は着岸位置(fill:forwards)に留めたまま、先に文言と幅を元へ戻す。
      // バッジは中央寄せのため、文言が短いままアイコンを交代すると
      // ボタン位置が着岸点からずれてカクつく
      await this.swapBadgeText(BADGE_TEXT);
      badge.style.width = "";
      await this.$nextTick();

      // 交代: 航海の揺れは2周期でちょうどニュートラルに戻っており、docked で
      // バッジ側の揺れも位相0(ニュートラル)から再開するため、姿勢が途切れない
      this.docked = true;
      this.voyaging = false;
      this.voyage = null;
      this.sailing = false;
    },
    scrollToFeatures() {
      const el = this.$refs.featuresRef;
      if (!el) return;
      const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      el.scrollIntoView({ behavior: reduceMotion ? "auto" : "smooth" });
    },
    animateStats() {
      const parsed = this.stats.map((s) => parseStatNumber(s.number));
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        this.displayStats = this.stats.map((s) => s.number);
        return;
      }
      const DURATION = 1200;
      const start = performance.now();
      const tick = (now) => {
        const t = Math.min((now - start) / DURATION, 1);
        const eased = 1 - Math.pow(1 - t, 3); // easeOutCubic
        this.displayStats = this.stats.map((s, i) => {
          const p = parsed[i];
          if (!p) return s.number;
          return `${Math.round(p.target * eased)}${p.suffix}`;
        });
        if (t < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    },
  },
};
</script>

