   App.vue の全要素トランジションと干渉しないよう、transition は各要素で明示する */
.theme-toggle {
  /* 見た目は 36px の円、ヒット領域は 44px 以上 */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  margin-right: -4px;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 50%;
  cursor: pointer;
  color: #d97706; /* 太陽: 暖色のアンバー */
}
.theme-toggle.is-dark {
  color: var(--c-accent-text); /* 月 */
}
.theme-toggle:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: 2px;
}

.theme-toggle-disc {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--c-bg-card);
  border: 1px solid var(--c-border);
  transition:
    background-color 0.25s ease,
    border-color 0.25s ease,
    transform 0.15s ease;
}
.theme-toggle:hover .theme-toggle-disc {
  background: var(--c-card-hover);
  border-color: var(--c-accent-border);
}
.theme-toggle:active .theme-toggle-disc {
  transform: scale(0.92);
}

/* 太陽(ライト)の状態が既定。ダークで月に変わる */
.theme-toggle-svg {
  display: block;
  transform: rotate(90deg);
  transition: transform 0.4s ease;
}
.theme-toggle.is-dark .theme-toggle-svg {
  transform: rotate(40deg);
}

.sun-moon {
  transform-origin: center center;
  transform: scale(0.55);
  transition: transform 0.4s ease;
}
.theme-toggle.is-dark .sun-moon {
  transform: scale(1);
}

/* マスク円: 太陽では本体の外へ退避、月では本体に重なって欠けを作る */
.moon-cut {
  transform: translate(16px, -3px);
  transition: transform 0.64s cubic-bezier(0.41, 0.64, 0.32, 1.575);
}
.theme-toggle.is-dark .moon-cut {
  transform: translate(0, 0);
}

/* 光線: 太陽では時計回りに順に現れ、月では即座に消える */
.sun-ray {
  transform-origin: center center;
  transform: scale(1);
  transition: transform 0.3s ease;
}
.sun-ray:nth-child(2) { transition-delay: 0.05s; }
.sun-ray:nth-child(3) { transition-delay: 0.1s; }
.sun-ray:nth-child(4) { transition-delay: 0.17s; }
.sun-ray:nth-child(5) { transition-delay: 0.25s; }
.sun-ray:nth-child(6) { transition-delay: 0.29s; }
.theme-toggle.is-dark .sun-ray {
  transform: scale(0);
  transition-delay: 0s;
}

